import asyncio
import httpx
import json

BASE_URL = "http://are-sidecar:8000/mcp"
HEADERS = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream"
}

async def main():
    async with httpx.AsyncClient(timeout=30.0) as client:
        # Initialize MCP session
        init_msg = {
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "task-client", "version": "1.0"}
            }
        }
        resp = await client.post(BASE_URL, json=init_msg, headers=HEADERS)
        print("Init response:", resp.status_code)
        print(resp.text[:500])

        # Send initialized notification
        init_notif = {"jsonrpc": "2.0", "method": "notifications/initialized"}
        await client.post(BASE_URL, json=init_notif, headers=HEADERS)

        # List tools
        tools_msg = {"jsonrpc": "2.0", "id": 2, "method": "tools/list", "params": {}}
        resp = await client.post(BASE_URL, json=tools_msg, headers=HEADERS)
        print("\nTools response:", resp.status_code)
        data = resp.json()
        if "result" in data:
            for t in data["result"].get("tools", [])[:30]:
                print(f"  - {t['name']}")
            total = len(data["result"].get("tools", []))
            print(f"  ... ({total} total tools)")

        # Call get_last_message_from_user
        call_msg = {
            "jsonrpc": "2.0",
            "id": 3,
            "method": "tools/call",
            "params": {
                "name": "AgentUserInterface__get_last_message_from_user",
                "arguments": {}
            }
        }
        resp = await client.post(BASE_URL, json=call_msg, headers=HEADERS)
        print("\nUser message response:", resp.status_code)
        print(resp.text)

asyncio.run(main())
