import asyncio
import httpx
import json
import sys

BASE_URL = "http://are-sidecar:8000/mcp"
HEADERS = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream"
}

class MCPClient:
    def __init__(self):
        self.client = None
        self.session_id = None
        self.call_id = 0

    async def connect(self):
        self.client = httpx.AsyncClient(timeout=60.0)
        init_msg = {
            "jsonrpc": "2.0", "id": 1, "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "task-client", "version": "1.0"}
            }
        }
        resp = await self.client.post(BASE_URL, json=init_msg, headers=HEADERS)
        self.session_id = resp.headers.get("mcp-session-id")
        print(f"Session: {self.session_id}")

        headers = {**HEADERS, "mcp-session-id": self.session_id}
        await self.client.post(BASE_URL, json={"jsonrpc": "2.0", "method": "notifications/initialized"}, headers=headers)

    async def call_tool(self, tool_name, arguments={}):
        self.call_id += 1
        headers = {**HEADERS, "mcp-session-id": self.session_id}
        msg = {
            "jsonrpc": "2.0", "id": self.call_id,
            "method": "tools/call",
            "params": {"name": tool_name, "arguments": arguments}
        }
        resp = await self.client.post(BASE_URL, json=msg, headers=headers)
        if resp.status_code != 200:
            print(f"ERROR {tool_name}: {resp.status_code} {resp.text}")
            return None
        text = resp.text
        for line in text.split('\n'):
            if line.startswith('data: '):
                data = json.loads(line[6:])
                # Extract the actual result text
                if "result" in data:
                    content = data["result"].get("content", [])
                    for c in content:
                        if c.get("type") == "text":
                            try:
                                return json.loads(c["text"])
                            except:
                                return c["text"]
                return data
        return None

    async def list_tools(self):
        self.call_id += 1
        headers = {**HEADERS, "mcp-session-id": self.session_id}
        msg = {"jsonrpc": "2.0", "id": self.call_id, "method": "tools/list", "params": {}}
        resp = await self.client.post(BASE_URL, json=msg, headers=headers)
        text = resp.text
        for line in text.split('\n'):
            if line.startswith('data: '):
                data = json.loads(line[6:])
                return data.get("result", {}).get("tools", [])
        return []

async def main():
    mcp = MCPClient()
    await mcp.connect()

    # List tools
    tools = await mcp.list_tools()
    print("=== AVAILABLE TOOLS ===")
    for t in tools:
        print(f"  {t['name']}")
    print(f"\nTotal: {len(tools)} tools")

    # Check time
    print("\n=== CURRENT TIME ===")
    result = await mcp.call_tool("are_get_time")
    print(json.dumps(result, indent=2))

    # Get contacts
    print("\n=== CONTACTS ===")
    result = await mcp.call_tool("Contacts__get_contacts")
    print(json.dumps(result, indent=2))

asyncio.run(main())
